#!/usr/bin/env python3
# **Do not edit this file.** The client is provided; each student implements
# the plugin they claimed under platform/plugins/.
"""CLI for the week06 node. Prints bytes as UTF-8 when possible, otherwise hex."""
from __future__ import annotations

import argparse
import sys
from pathlib import Path

import grpc

HERE = Path(__file__).resolve().parent.parent
if str(HERE) not in sys.path:
    sys.path.insert(0, str(HERE))

from platform import node_pb2, node_pb2_grpc  # noqa: E402


def _b(text: str) -> bytes:
    if text.startswith("hex:"):
        return bytes.fromhex(text[4:])
    return text.encode("utf-8")


def _show(b: bytes) -> str:
    try:
        s = b.decode("utf-8")
        if s.isprintable() or "\n" in s:
            return s
    except Exception:
        pass
    return "hex:" + b.hex()


def _modes(args: argparse.Namespace) -> node_pb2.Modes:
    return node_pb2.Modes(
        partitioning=getattr(args, "partitioning", "") or "",
        replication=getattr(args, "replication", "") or "",
        write_completion=getattr(args, "write_completion", "") or "",
        leader_replication=getattr(args, "leader_replication", "") or "",
        conflicts=getattr(args, "conflicts", "") or "",
        request_routing=getattr(args, "request_routing", "") or "",
        leader_election=getattr(args, "leader_election", "") or "",
        session_models=getattr(args, "session_models", "") or "",
        processing_guarantees=getattr(args, "processing_guarantees", "") or "",
        resume=getattr(args, "resume", "") or "",
        atomic_commit=getattr(args, "atomic_commit", "") or "",
    )


def _stub(addr: str) -> node_pb2_grpc.NodeStub:
    channel = grpc.insecure_channel(addr)
    return node_pb2_grpc.NodeStub(channel)


def _add_mode_flags(p: argparse.ArgumentParser) -> None:
    p.add_argument("--partitioning", default="")
    p.add_argument("--replication", default="")
    p.add_argument("--write-completion", default="")
    p.add_argument("--leader-replication", default="")
    p.add_argument("--conflicts", default="")
    p.add_argument("--request-routing", default="")
    p.add_argument("--leader-election", default="")
    p.add_argument("--session-models", default="")
    p.add_argument("--processing-guarantees", default="")
    p.add_argument("--resume", default="")
    p.add_argument("--atomic-commit", default="")
    p.add_argument("--session-id", default="")


def main(argv=None) -> int:
    ap = argparse.ArgumentParser(description="CSC36000 week06 client")
    ap.add_argument("--addr", default="127.0.0.1:9600")
    sub = ap.add_subparsers(dest="cmd", required=True)

    p = sub.add_parser("health")
    p = sub.add_parser("status")

    p = sub.add_parser("write")
    p.add_argument("key")
    p.add_argument("value")
    p.add_argument("--idempotency-key", default="")
    _add_mode_flags(p)

    p = sub.add_parser("read")
    p.add_argument("key")
    _add_mode_flags(p)

    p = sub.add_parser("fault")
    p.add_argument("--pause", choices=["on", "off"])
    p.add_argument("--delay-ms", type=int)
    p.add_argument("--drop-to", default="", help="comma-separated node ids")
    p.add_argument("--isolate", choices=["on", "off"])

    p = sub.add_parser("add-node")
    p.add_argument("node_id")
    p.add_argument("host")
    p.add_argument("port", type=int)
    _add_mode_flags(p)

    p = sub.add_parser("pin")
    p.add_argument("key")
    p.add_argument("node_id")
    _add_mode_flags(p)

    p = sub.add_parser("rebalance")
    _add_mode_flags(p)

    p = sub.add_parser("elect")
    _add_mode_flags(p)

    p = sub.add_parser("run-start")
    p.add_argument("run_id")
    p.add_argument("steps", nargs="+", help="key=value pairs")
    _add_mode_flags(p)

    p = sub.add_parser("run-get")
    p.add_argument("run_id")

    p = sub.add_parser("run-resume")
    p.add_argument("run_id")
    _add_mode_flags(p)

    p = sub.add_parser("txn")
    p.add_argument("txn_id")
    p.add_argument("key_a")
    p.add_argument("value_a")
    p.add_argument("key_b")
    p.add_argument("value_b")
    _add_mode_flags(p)

    args = ap.parse_args(argv)
    stub = _stub(args.addr)

    if args.cmd == "health":
        r = stub.Health(node_pb2.HealthRequest(), timeout=2)
        print(f"ok={r.ok} node_id={r.node_id}")
        return 0 if r.ok else 1

    if args.cmd == "status":
        r = stub.Status(node_pb2.StatusRequest(), timeout=2)
        print(
            f"ok={r.ok} node_id={r.node_id} leader={r.leader} term={r.term} "
            f"key_count={r.key_count} peers={list(r.peers)}"
        )
        print(f"faults pause={r.faults.pause} delay_ms={r.faults.delay_ms} drop_to={list(r.faults.drop_to)}")
        if r.keys_per_node:
            print("keys_per_node", dict(r.keys_per_node))
        return 0 if r.ok else 1

    if args.cmd == "write":
        r = stub.Write(
            node_pb2.WriteRequest(
                key=_b(args.key),
                value=_b(args.value),
                session_id=args.session_id,
                modes=_modes(args),
                idempotency_key=args.idempotency_key,
            ),
            timeout=8,
        )
        print(f"ok={r.ok} error={r.error!r} owner={r.owner} acked_by={list(r.acked_by)}")
        return 0 if r.ok else 1

    if args.cmd == "read":
        r = stub.Read(
            node_pb2.ReadRequest(key=_b(args.key), session_id=args.session_id, modes=_modes(args)),
            timeout=8,
        )
        print(
            f"ok={r.ok} error={r.error!r} found={r.found} served_by={r.served_by} value={_show(r.value)}"
        )
        return 0 if r.ok else 1

    if args.cmd == "fault":
        req = node_pb2.FaultRequest()
        if args.pause:
            req.set_pause = True
            req.pause = args.pause == "on"
        if args.delay_ms is not None:
            req.set_delay = True
            req.delay_ms = args.delay_ms
        if args.drop_to != "":
            req.set_drop_to = True
            if args.drop_to:
                req.drop_to.extend(args.drop_to.split(","))
        if args.isolate:
            req.set_isolate = True
            req.isolate = args.isolate == "on"
        r = stub.Fault(req, timeout=2)
        print(f"ok={r.ok} pause={r.faults.pause} drop_to={list(r.faults.drop_to)} delay_ms={r.faults.delay_ms}")
        return 0 if r.ok else 1

    if args.cmd == "add-node":
        r = stub.AddNode(
            node_pb2.AddNodeRequest(
                node_id=args.node_id, host=args.host, port=args.port, modes=_modes(args)
            ),
            timeout=4,
        )
        print(f"ok={r.ok} peers={list(r.peers)}")
        return 0 if r.ok else 1

    if args.cmd == "pin":
        r = stub.AddNode(
            node_pb2.AddNodeRequest(node_id=args.node_id, pin_key=_b(args.key), modes=_modes(args)),
            timeout=4,
        )
        print(f"ok={r.ok} peers={list(r.peers)}")
        return 0 if r.ok else 1

    if args.cmd == "rebalance":
        r = stub.Rebalance(node_pb2.RebalanceRequest(modes=_modes(args)), timeout=4)
        print(f"ok={r.ok} keys_per_node={dict(r.keys_per_node)}")
        return 0 if r.ok else 1

    if args.cmd == "elect":
        r = stub.Elect(node_pb2.ElectRequest(candidate="", term=0, modes=_modes(args)), timeout=4)
        print(f"ok={r.ok} granted={r.granted} leader={r.leader} term={r.term} error={r.error!r}")
        return 0 if r.ok else 1

    if args.cmd == "run-start":
        steps = []
        for item in args.steps:
            k, v = item.split("=", 1)
            steps.append(node_pb2.RunStep(key=_b(k), value=_b(v)))
        r = stub.RunStart(
            node_pb2.RunStartRequest(run_id=args.run_id, modes=_modes(args), steps=steps),
            timeout=12,
        )
        print(f"ok={r.ok} state={r.state} next_step={r.next_step} applied={list(r.applied)} error={r.error!r}")
        return 0 if r.ok else 1

    if args.cmd == "run-get":
        r = stub.RunGet(node_pb2.RunGetRequest(run_id=args.run_id), timeout=4)
        print(f"ok={r.ok} state={r.state} next_step={r.next_step} applied={list(r.applied)}")
        return 0 if r.ok else 1

    if args.cmd == "run-resume":
        r = stub.RunResume(
            node_pb2.RunResumeRequest(run_id=args.run_id, modes=_modes(args)), timeout=12
        )
        print(f"ok={r.ok} state={r.state} next_step={r.next_step} applied={list(r.applied)}")
        return 0 if r.ok else 1

    if args.cmd == "txn":
        r = stub.Txn(
            node_pb2.TxnRequest(
                txn_id=args.txn_id,
                key_a=_b(args.key_a),
                value_a=_b(args.value_a),
                key_b=_b(args.key_b),
                value_b=_b(args.value_b),
                modes=_modes(args),
            ),
            timeout=12,
        )
        print(f"ok={r.ok} state={r.state} error={r.error!r}")
        return 0 if r.ok else 1

    return 2


if __name__ == "__main__":
    raise SystemExit(main())
